def clip_by_plane(pcd, plane_model, keep_above=True):
    a, b, c, d = plane_model
    points = np.asarray(pcd.points)

    # plane equation: ax + by + cz + d
    dist = points @ np.array([a, b, c]) + d

    if keep_above:
        mask = dist > 0
    else:
        mask = dist < 0

    return pcd.select_by_index(np.where(mask)[0])


clipped = clip_by_plane(pcd, planes[0][0], keep_above=True)
clipped.paint_uniform_color([1, 1, 0])  # yellow
geometries.append(clipped)



