def plane_mesh_from_points(plane_model, cloud, color=[0,1,1]):
    a, b, c, d = plane_model
    n = np.array([a, b, c])
    n = n / np.linalg.norm(n)

    points = np.asarray(cloud.points)

    # --- 1. build plane basis
    u, v = get_plane_basis(n)

    # --- 2. project to 2D plane coordinates
    origin = points.mean(axis=0)

    rel = points - origin
    u_coords = rel @ u
    v_coords = rel @ v


## (A)
    # pts_2d = np.stack([u_coords, v_coords], axis=1)

    # # --- 3. convex hull in 2D
    # hull = o3d.geometry.PointCloud()
    # hull.points = o3d.utility.Vector3dVector(
    #     np.column_stack([u_coords, v_coords, np.zeros_like(u_coords)])
    # )

    # hull_mesh, _ = hull.compute_convex_hull()

    # hull_vertices_2d = np.asarray(hull_mesh.vertices)[:, :2]

    # # --- 4. map back to 3D
    # vertices_3d = []
    # for uv in hull_vertices_2d:
    #     p = origin + uv[0]*u + uv[1]*v
    #     vertices_3d.append(p)
## QH6154 Qhull precision error: Initial simplex is flat

## (B)
    # vertices_3d = np.array(vertices_3d)
    u_min, u_max = u_coords.min(), u_coords.max()
    v_min, v_max = v_coords.min(), v_coords.max()
    
    corners = np.array([
        [u_min, v_min],
        [u_max, v_min],
        [u_max, v_max],
        [u_min, v_max]
    ])
    
    vertices_3d = origin + corners[:,0:1]*u + corners[:,1:2]*v
## ---

    # --- 5. triangulate (fan)
    triangles = []
    for i in range(1, len(vertices_3d)-1):
        triangles.append([0, i, i+1])

    mesh = o3d.geometry.TriangleMesh()
    mesh.vertices = o3d.utility.Vector3dVector(vertices_3d)
    mesh.triangles = o3d.utility.Vector3iVector(triangles)

    mesh.paint_uniform_color(color)
    mesh.compute_vertex_normals()

    return mesh

